  1195→// runExplainCommit explains a specific commit.
  1196→func runExplainCommit(w io.Writer, commitRef string) error {
  1197→	repo, err := openRepository()
  1198→	if err != nil {
  1199→		return fmt.Errorf("not a git repository: %w", err)
  1200→	}
  1201→
  1202→	// Resolve the commit reference
  1203→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
  1204→	if err != nil {
  1205→		return fmt.Errorf("commit not found: %s", commitRef)
  1206→	}
  1207→
  1208→	commit, err := repo.CommitObject(*hash)
  1209→	if err != nil {
  1210→		return fmt.Errorf("failed to get commit: %w", err)
  1211→	}
  1212→
  1213→	// Get files changed in this commit (diff from parent to current)
  1214→	var files []string
  1215→	commitTree, err := commit.Tree()
  1216→	if err == nil && commit.NumParents() > 0 {
  1217→		parent, parentErr := commit.Parent(0)
  1218→		if parentErr == nil {
  1219→			parentTree, treeErr := parent.Tree()
  1220→			if treeErr == nil {
  1221→				// Diff from parent to current commit to show what changed
  1222→				changes, diffErr := parentTree.Diff(commitTree)
  1223→				if diffErr == nil {
  1224→					for _, change := range changes {
  1225→						name := change.To.Name
  1226→						if name == "" {
  1227→							name = change.From.Name
  1228→						}
  1229→						files = append(files, name)
  1230→					}
  1231→				}
  1232→			}
  1233→		}
  1234→	}
  1235→
  1236→	// Check for Entire metadata - try multiple trailer types
  1237→	metadataDir, hasMetadata := trailers.ParseMetadata(commit.Message)
  1238→	sessionID, hasSession := trailers.ParseSession(commit.Message)
  1239→	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
  1240→
  1241→	// If no session trailer, try to extract from metadata path.
  1242→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
