  1256→	info := &commitInfo{
  1257→		SHA:       fullSHA,
  1258→		ShortSHA:  shortSHA,
  1259→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
  1260→		Author:    commit.Author.Name,
  1261→		Email:     commit.Author.Email,
  1262→		Date:      commit.Author.When,
  1263→		Files:     files,
  1264→		HasEntire: hasMetadata || hasSession || hasCheckpoint,
  1265→		SessionID: sessionID,
  1266→	}
