```go
// CheckpointAuthor contains author information for a checkpoint.
type CheckpointAuthor struct {
	Name  string
	Email string
}

// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/sessions commit history.
// Returns the author of the commit that first created the checkpoint's metadata.json file.
// Returns empty author if checkpoint not found or on error.
func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (CheckpointAuthor, error) {
	_ = ctx // Reserved for future use

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return CheckpointAuthor{}, nil // No sessions branch, no author
	}

	// Path to the checkpoint's metadata file
	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName

	// Walk commit history looking for the commit that added this file
	iter, err := s.repo.Log(&git.LogOptions{
		From:  ref.Hash(),
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return CheckpointAuthor{}, nil
	}
	defer iter.Close()

	var author CheckpointAuthor
	var foundCommit *object.Commit

	err = iter.ForEach(func(c *object.Commit) error {
		// Check if this commit has the metadata file
		tree, treeErr := c.Tree()
		if treeErr != nil {
			return nil // Continue
		}

		_, fileErr := tree.File(metadataPath)
		if fileErr != nil {
			// File doesn't exist in this commit - we've gone past the creation point
			// The previous commit (foundCommit) was the one that added it
			if foundCommit != nil {
				return errStopIteration
			}
			return nil
		}

		// File exists - this commit has it (might be creator or modifier)
		foundCommit = c
		author = CheckpointAuthor{
			Name:  c.Author.Name,
			Email: c.Author.Email,
		}
		return nil
	})

	// If we found a commit with the file, return its author
	// (this is the oldest commit that has the file, i.e., the creator)
	return author, nil
}
```

Note: Add `var errStopIteration = errors.New("stop iteration")` if not already defined in the file.

